-- PT115-S4-Q2. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT115-S4-Q2$batch07$ AND q.stimulus=$batch07$Tom: Critics of recent high court decisions claim that judges’ willingness to abide by earlier decisions is necessary to avoid legal chaos. Since high courts of the past often repudiated legal precedents and no harm to the legal system ensued, these critics’ objections must be politically motivated and ought to be ignored.
Mary: High courts have repudiated precedents in the past, but they were careful to do so only when the previous rulings were old and had clearly become outdated. The recently overturned rulings were themselves recent. Overturning any recent legal ruling diminishes the law, which comes to be viewed as unstable and capricious.$batch07$ AND q.prompt=$batch07$Which one of the following most accurately expresses the point at issue between Tom and Mary?$batch07$ AND q.correct_choice=$batch07$A$batch07$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT115-S4-Q2$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT115-S4-Q2$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Tom's Position$batch07$, $batch07$Past high courts often repudiated precedents and no harm followed. So the critics' worry about legal chaos is politically motivated and should be ignored. In short: the recent reversals won't hurt the legal system.$batch07$), (1, $batch07$Mary's Position$batch07$, $batch07$Past courts only overturned old, outdated rulings. These rulings were recent, and overturning any recent ruling diminishes the law, making it look unstable and capricious.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Mary grants Tom's fact (courts have repudiated precedents before) and then attacks Tom's analogy: the past cases were old rulings, these are recent ones. So the real question is whether *these* reversals will do damage. Tom says no harm, as in the past. Mary says it diminishes the law.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether overturning recent precedents will harm the legal system.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT115-S4-Q2$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Tom uses the past to argue that no harm will follow and the chaos worry can be ignored. Mary says overturning a recent ruling "diminishes the law". That is harm versus no harm.$batch07$), ($batch07$B$batch07$, $batch07$This is the most popular wrong answer. Read Tom closely: Tom says the *critics' objections* are politically motivated, not the court's decisions. And Mary says nothing about anyone's motives. Neither side is supported.$batch07$), ($batch07$C$batch07$, $batch07$Mary never questions whether the critics actually made the claim Tom cites. Mary argues about the claim, not about who said it.$batch07$), ($batch07$D$batch07$, $batch07$Mary implies outdated precedents may be overturned, but whether they *need* to be is a stronger claim. Tom says nothing about outdated precedents.$batch07$), ($batch07$E$batch07$, $batch07$Neither speaker talks about decisions that "seem progressive" or how fast they go out of date.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT115-S4-Q2$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
